	bad = 0;
	for (v = 0; v < 16; v++) {
		voice(v, 0, 0x01000000UL + 0x111 * v, 0x00ABCD00UL + v, 0x00123400UL + v, 0x00012345UL * (v + 1), 0x4000 + v);
		V(v, V_CTRL) = C_PCM16 | C_LOOP | ((v & 1) ? C_AUD2 : 0);
	}
	for (v = 0; v < 16; v++) {
		if (V(v, V_ADDR) != 0x01000000UL + 0x111 * v) bad++;
		if (V(v, V_LEN) != 0x00ABCD00UL + v) bad++;
		if (V(v, V_LOOP) != 0x00123400UL + v) bad++;
		if (V(v, V_STEP) != 0x00012345UL * (v + 1)) bad++;
		if (V(v, V_VOL) != 0x4000UL + v) bad++;
		if (V(v, V_CTRL) != ((C_PCM16 | C_LOOP | ((v & 1) ? C_AUD2 : 0)) & 0x1FC)) bad++;
	}
	P(A_MASTER) = 0x1234; P(A_MASTR2) = 0x5678; P(A_IRQEN) = 0xA5A5;
	if (P(A_MASTER) != 0x1234 || P(A_MASTR2) != 0x5678 || P(A_IRQEN) != 0xA5A5) bad++;
	if (P(A_PLAY) != 0) bad++;
	check(0, bad, 0);
	P(A_MASTER) = 0x8080; P(A_MASTR2) = 0x8080; P(A_IRQEN) = 0;

	/* 1-4: a constant PCM16 from each bank on AUD3 (volume and master unity: the output is the sample itself);
	 * 5-8: the same on AUD2 */
	P(A_CTRL) = 1;
	for (b = 0; b < 8; b++) {
		u32 a = bank_addr[b & 3] + 0x1000 * b;
		u16 val = 0x1000 * (b + 1) + 0x123;
		fill16(a, val, 0, 0);
		voice(0, C_PCM16 | C_LOOP | ((b >= 4) ? C_AUD2 : 0), a, 64, 0, 0x10000UL, 0x8080);
		V(0, V_CTRL) = C_PCM16 | C_LOOP | ((b >= 4) ? C_AUD2 : 0) | C_PLAY;
		x = wait_events(1, 5) ? P((b >= 4) ? A_OUT44 : A_OUT48) : 0xDEAD0000UL;
		check(1 + b, x, ((u32)val << 16) | val);
		V(0, V_CTRL) = C_STOP; wait_idle(1);
	}
	/* 9: PCM8 stereo from SDRAM (bytes $40 / $C0 -> $4000 / $C000) */
	{
		volatile u8 *p = (volatile u8 *)0x03010000UL;
		int i;
		for (i = 0; i < 128; i += 2) { p[i] = 0x40; p[i + 1] = 0xC0; }
		voice(0, C_PCM8 | C_STEREO | C_LOOP, 0x03010000UL, 64, 0, 0x10000UL, 0x8080);
		V(0, V_CTRL) = C_PCM8 | C_STEREO | C_LOOP | C_PLAY;
		x = wait_events(1, 5) ? P(A_OUT48) : 0xDEAD0000UL;
		check(9, x, 0x4000C000UL);
		V(0, V_CTRL) = C_STOP; wait_idle(1);
	}
	/* 10: two voices add up (SDRAM $1000 + SRAM $0800); 11: half volume ($40) */
	fill16(0x03020000UL, 0x1000, 0, 0);
	fill16(0x00220000UL, 0x0800, 0, 0);
	voice(0, C_PCM16 | C_LOOP, 0x03020000UL, 64, 0, 0x10000UL, 0x8080);
	voice(2, C_PCM16 | C_LOOP, 0x00220000UL, 64, 0, 0x10000UL, 0x8080);
	V(0, V_CTRL) = C_PCM16 | C_LOOP | C_PLAY;
	V(2, V_CTRL) = C_PCM16 | C_LOOP | C_PLAY;
	x = wait_events(5, 5) ? P(A_OUT48) : 0xDEAD0000UL;
	check(10, x, 0x18001800UL);
	V(2, V_CTRL) = C_STOP; wait_idle(4);
	V(0, V_VOL) = 0x4040;
	x = wait_events(1, 5) ? P(A_OUT48) : 0xDEAD0000UL;
	check(11, x, 0x08000800UL);
	/* 12: STOP ramps down and ends; the output goes back to 0 */
	V(0, V_CTRL) = C_STOP;
	x = wait_idle(1);
	pause(3000);											/* (the pass after the end) */
	check(12, x ? P(A_OUT48) : 0xDEAD0000UL, 0);
	/* 13: a one-shot of 480 frames ends with V_POS = LEN and its EVENT bit; 14: that event is GAVIN bit 47 */
	P(A_EVENT) = 0xFFFF;
	P(A_IRQEN) = 1 << 3;
	IRQ_PEND2 = 0x8000;
	fill16(0x00510000UL, 0x0100, 0, 0);
	voice(3, C_PCM16, 0x00510000UL, 480, 0, 0x10000UL, 0x8080);
	V(3, V_CTRL) = C_PCM16 | C_PLAY;
	x = wait_idle(1 << 3);
	pause(3000);											/* (V_POS is refreshed every 2.6 us) */
	check(13, x ? ((V(3, V_POS) << 16) | (P(A_EVENT) & 0xFFFF)) : 0xDEAD0000UL, (480UL << 16) | (1 << 3));
	{ u32 t; for (t = 0; t < 1000; t++) ; }
	check(14, IRQ_PEND2 & 0x8000, 0x8000);
	IRQ_PEND2 = 0x8000; P(A_IRQEN) = 0; P(A_EVENT) = 0xFFFF;
	/* 15: rate: a voice on each DAC (silent), started together; V_POS ratio x 10000 = 48000 / 44100 = 10884 */
	voice(4, C_PCM8, 0x03100000UL, 0xFFFFFFUL, 0, 0x10000UL, 0);
	voice(5, C_PCM8 | C_AUD2, 0x03100000UL, 0xFFFFFFUL, 0, 0x10000UL, 0);
	V(4, V_CTRL) = C_PCM8 | C_PLAY;
	V(5, V_CTRL) = C_PCM8 | C_AUD2 | C_PLAY;
	{ u32 t; for (t = 0; V(5, V_POS) < 20000 && t < 4000000UL; t++) ; }
	{
		u32 a3 = V(4, V_POS), a2 = V(5, V_POS);
		D(30) = a3; D(31) = a2;
		x = a2 ? (a3 * 10000UL) / a2 : 0;
		D(15) = x; D(55) = 10884;
		if (x < 10874 || x > 10894) fail(15);
	}
	V(4, V_CTRL) = C_STOP; V(5, V_CTRL) = C_STOP; wait_idle(0x30);
	/* 16: a voice outside the banks plays silence and sets STARVE */
	P(A_STATUS) = 3;
	voice(6, C_PCM16 | C_LOOP, 0x00C00000UL, 64, 0, 0x10000UL, 0x8080);
	V(6, V_CTRL) = C_PCM16 | C_LOOP | C_PLAY;
	{ u32 t; for (t = 0; !(P(A_STATUS) & 2) && t < 2000000UL; t++) ; }
	check(16, ((P(A_STATUS) & 2) << 16) | (P(A_OUT48) & 0xFFFF), 2UL << 16);
	V(6, V_CTRL) = C_STOP; wait_idle(1 << 6);
	P(A_STATUS) = 3;
	check(17, P(A_STATUS) & 2, 0);
	/* 18: the test tone (no voice): OUT48 changes, both halves equal */
	P(A_CTRL) = 2;
	{
		u32 t, a = P(A_OUT48), c = 0;
		for (t = 0; t < 200000UL; t++) { u32 y = P(A_OUT48); if (y != a) { c++; a = y; } if ((y >> 16) != (y & 0xFFFF)) c |= 0x80000000UL; }
		D(18) = c;
		if (c < 50 || (c & 0x80000000UL)) fail(18);
	}
