/* scales and a chord: one period of a sine (64 frames) in SDRAM, the pitch from V_STEP */
static const short sine64[64] = {
	0, 785, 1560, 2315, 3040, 3727, 4365, 4947, 5465, 5913, 6284, 6574, 6779, 6898, 6929, 6872,
	6727, 6497, 6185, 5795, 5332, 4802, 4211, 3566, 2875, 2146, 1388, 609, -181, -965, -1735, -2481,
	-3195, -3866, -4488, -5052, -5551, -5978, -6327, -6595, -6777, -6873, -6880, -6799, -6631, -6378, -6044, -5633,
	-5151, -4604, -3999, -3343, -2645, -1913, -1158, -388, 389, 1159, 1914, 2646, 3344, 4000, 4605, 5152 };
static const u32 notes[8] = { 26163, 29366, 32963, 34923, 39200, 44000, 49388, 52325 };	/* C4..C5 in Hz x 100 */

static u32 step_for(u32 hz100, u32 rate)		/* 16.16 frames of the 64-frame period per output sample */
{
	return (u32)(((unsigned long long)hz100 * 64ULL * 65536ULL) / (100ULL * rate));
}


static void demo(void)
{
	volatile u8 *p = (volatile u8 *)0x03200000UL;
	int i, v;
	for (i = 0; i < 64; i++) { p[2 * i] = sine64[i] & 0xFF; p[2 * i + 1] = (sine64[i] >> 8) & 0xFF; }
	all_off();
	P(A_MASTER) = 0x8080; P(A_MASTR2) = 0x8080;
	P(A_CTRL) = 1;
	while (timers_jiffies() < g1t_end) {
		/* the scale on AUD3 (48 kHz), then on AUD2 (44.1 kHz), then the C major chord on both */
		for (v = 0; v < 2; v++) for (i = 0; i < 8; i++) {
			voice(0, C_PCM16 | C_LOOP | (v ? C_AUD2 : 0), 0x03200000UL, 64, 0, step_for(notes[i], v ? 44100 : 48000), 0x6060);
			V(0, V_CTRL) = C_PCM16 | C_LOOP | (v ? C_AUD2 : 0) | C_PLAY;
			pause(150000);
			V(0, V_CTRL) = C_STOP;
			pause(30000);
			R(0x04)++;
		}
		for (i = 0; i < 6; i++) {
			int n = (i % 3 == 0) ? 0 : (i % 3 == 1) ? 2 : 4;		/* C, E, G */
			int out2 = (i >= 3);
			voice(2 + i, C_PCM16 | C_LOOP | (out2 ? C_AUD2 : 0), 0x03200000UL, 64, 0, step_for(notes[n], out2 ? 44100 : 48000),
				  (i & 1) ? 0x2050 : 0x5020);
			V(2 + i, V_CTRL) = C_PCM16 | C_LOOP | (out2 ? C_AUD2 : 0) | C_PLAY;
		}
		pause(600000);
		for (i = 0; i < 6; i++) V(2 + i, V_CTRL) = C_STOP;
		pause(300000);
	}
}

int g1t_dac_main(void)
{
	u32 mode = R(0x00);
	R(0x04) = 0; R(0x0C) = 0; R(0x14) = 0; R(0x18) = 0;
	if (mode == 0) {
		int k;
		for (k = 0; k < 64; k++) D(k) = 0;
		nerr = 0;
		functional();
		R(0x0C) = nerr;
		R(0x08) = 0x600DF00DUL;
		return 0;
	}
	R(0x08) = 0x600DF00DUL;
	if (mode == 1) {
		all_off();
		P(A_CTRL) = 1;
		voice(0, C_PCM8, 0x03100000UL, 0xFFFFFFUL, 0, 0x10000UL, 0);
		voice(1, C_PCM8 | C_AUD2, 0x03100000UL, 0xFFFFFFUL, 0, 0x10000UL, 0);
		V(0, V_CTRL) = C_PCM8 | C_PLAY;
		V(1, V_CTRL) = C_PCM8 | C_AUD2 | C_PLAY;
		while (timers_jiffies() < g1t_end) { R(0x14) = V(0, V_POS); R(0x18) = V(1, V_POS); R(0x04)++; }
	}
	if (mode == 2) {
		all_off();
		P(A_MASTER) = 0x8080; P(A_MASTR2) = 0x8080;
		P(A_CTRL) = 2;
		return 0;
	}
	if (mode == 3) demo();
	return 0;
	return 0;
}
